import React, { useState } from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";
import { apiAddUser } from "../service/user";

const Overlay = styled.div`
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background-color: rgba(0, 0, 0, 0.5);
  display: flex; justify-content: center; align-items: center;
  z-index: 999;
`;

const Popup = styled.div`
  background: white;
  padding: 30px;
  border-radius: 10px;
  width: 500px;
  position: relative;
`;

const CloseButton = styled.button`
  position: absolute;
  top: 10px; right: 10px;
  background: none;
  border: none;
  font-size: 20px;
  cursor: pointer;
`;

const InputGroup = styled.div`
  margin-bottom: 15px;
`;

const Label = styled.label`
  display: block;
  margin-bottom: 5px;
  font-weight: bold;
`;

const Input = styled.input`
  width: 100%;
  padding: 8px;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const PasswordWrapper = styled.div`
  position: relative;
`;

const EyeIcon = styled.span`
  position: absolute;
  right: 10px; top: 50%;
  transform: translateY(-50%);
  cursor: pointer;
  font-size: 18px;
`;

const Button = styled.button`
  padding: 10px 15px;
  background-color: #007bff;
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;
`;

const ErrorMsg = styled.div`
  color: red;
  font-size: 13px;
`;

const AddUserPopup = ({ onClose }) => {
  const { t } = useTranslation();
  const [formData, setFormData] = useState({
    email: "",
    password: "",
    phone: "",
    username: "",
    address: "",
    birthday: "",
    gender: "",
    career: "",
    workplace: "",
  });

  const [errors, setErrors] = useState({});
  const [showPassword, setShowPassword] = useState(false);

  const validate = () => {
    const errs = {};
    if (!formData.email.includes("@")) errs.email = "Email không hợp lệ";
    if (formData.password.length < 6) errs.password = "Mật khẩu ít nhất 6 ký tự";
    if (!formData.username) errs.username = "Tên không được để trống";
    if (!formData.phone.match(/^[0-9]{9,11}$/)) errs.phone = "Số điện thoại không hợp lệ";
    if (!formData.birthday) errs.birthday = "Vui lòng chọn ngày sinh";
    return errs;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async () => {
    const validationErrors = validate();
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0) return;

    try {
      await apiAddUser(formData);
      alert("Thêm người dùng thành công!");
      onClose();
    } catch (err) {
      alert("Có lỗi xảy ra khi thêm người dùng.");
    }
  };

  return (
    <Overlay>
      <Popup>
        <CloseButton onClick={onClose}>×</CloseButton>
        <h2>{t("Thêm người dùng")}</h2>

        {[
          { name: "email", label: "Email", type: "email" },
          { name: "username", label: "Tên người dùng", type: "text" },
          { name: "phone", label: "Số điện thoại", type: "text" },
          { name: "address", label: "Địa chỉ", type: "text" },
          { name: "birthday", label: "Ngày sinh", type: "date" },
          { name: "gender", label: "Giới tính", type: "text" },
          { name: "career", label: "Nghề nghiệp", type: "text" },
          { name: "workplace", label: "Nơi làm việc", type: "text" },
        ].map(({ name, label, type }) => (
          <InputGroup key={name}>
            <Label>{label}</Label>
            <Input
              type={type}
              name={name}
              value={formData[name]}
              onChange={handleChange}
            />
            {errors[name] && <ErrorMsg>{errors[name]}</ErrorMsg>}
          </InputGroup>
        ))}

        <InputGroup>
          <Label>Mật khẩu</Label>
          <PasswordWrapper>
            <Input
              type={showPassword ? "text" : "password"}
              name="password"
              value={formData.password}
              onChange={handleChange}
            />
            <EyeIcon onClick={() => setShowPassword(!showPassword)}>
              {showPassword ? "🙈" : "👁️"}
            </EyeIcon>
          </PasswordWrapper>
          {errors.password && <ErrorMsg>{errors.password}</ErrorMsg>}
        </InputGroup>

        <Button onClick={handleSubmit}>{t("Xác nhận")}</Button>
      </Popup>
    </Overlay>
  );
};

export default AddUserPopup;
